    (67, None, 'Przestrzeń problemu', 'Stan początkowy, stany pośrednie, cel i operatory, które je łączą – razem z reprezentacją celu i ograniczeniami.'),
    (68, None, 'Problem słabo określony', 'Maksymalna niejasność co do celu, operatorów i ograniczeń – znany jest tylko stan początkowy.'),
