    (69, '69.3', 'Heurystyka', 'Świadomie stosowany zestaw reguł (intuicje, triki, wskazówki); nie gwarantuje sukcesu, dopuszcza indywidualną interpretację.'),
    (69, '69.4', 'Przeszukiwanie losowe (prób i błędów)', 'Przypadkowe zestawy kroków.'),
    (69, '69.5', 'Strategia „ciepło–zimno”', 'Posuwanie się do celu według wskazówek o zbliżaniu się – strategia oparta na zasadzie bliskości.'),
    (69, '69.6', 'Redukcja różnicy („wspinaczka”)', 'Każdy krok ma maksymalnie zmniejszyć różnicę między stanem aktualnym a celem; ryzyko „wspięcia się na niewłaściwy szczyt”.'),
    (69, '69.7', 'Analiza środków i celów', 'Podział problemu na podproblemy z własnymi celami, podporządkowanymi celowi głównemu (Wieża z Hanoi).'),
    (70, '70.1', 'Planowanie przez modelowanie', 'Tworzymy realny lub umysłowy model sytuacji i wykonujemy na nim odwracalne operacje – bez kosztów w rzeczywistości.'),
    (70, '70.2', 'Planowanie przez analogię', 'Przenosimy zależności z jednej dziedziny do drugiej na podstawie podobieństwa relacji między elementami.'),
