    (59, None, 'Kryterium przyjęcia i odrzucenia (GMP)', 'GMP powyżej kryterium przyjęcia – szybkie „tak”; poniżej kryterium odrzucenia – szybkie „nie”; pomiędzy – sprawdzanie cech definicyjnych.'),
    (60, None, 'Hierarchia pojęć (Rosch)', 'Poziom nadrzędny (pojazdy – bardzo ogólne), podstawowy (samochody – uprzywilejowany), podrzędny (Fiat, BMW – wiele szczegółowych cech).'),
